// Package consoleout carries the built Next.js export so the Go binary can serve it.
//
// The files are generated by `make console` and copied here by the build. This file is
// the only thing checked in, so the package always exists and a plain `go build` works
// without Node.
package consoleout

import "embed"

// Files is the built console.
//
//go:embed all:assets
var Files embed.FS
